<template><view class="shell"><TopBar back/><view class="eyebrow">两件小事，就能开演</view><view class="title">给日子，<text class="line-break"> </text><text class="highlight">加一点戏。</text></view><text class="label">一天大概想存多少？</text><view class="pills"><button v-for="n in [10,20,30]" :key="n" class="pill" :class="{active:daily===String(n)}" @click="daily=String(n)">¥{{n}}</button></view><view class="spacer"></view><view class="field"><input class="field-input" type="number" v-model="daily" placeholder="自定义金额，1–200 元" maxlength="3"/></view><view class="muted">只是安排故事的参考，今天不存也没关系。</view><text class="label">选一个花钱小习惯</text><view class="pills"><button v-for="h in habits" :key="h.key" class="pill" :class="{active:habit===h.key}" @click="habit=h.key">{{h.name}}</button></view><view class="spacer"></view><view class="muted">人设纯属虚构，想象一下就好。</view><button class="primary" :disabled="busy" @click="start">{{busy?'正在布置小店…':'开始假装花钱 ↗'}}</button><view v-if="error" class="error">{{error}}</view></view></template>
<script setup>
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import TopBar from '../../components/jdml/TopBar.vue';import {api,habits,home,parseMoney} from '../../services/api';
const daily=ref('20'),habit=ref('milk_tea'),busy=ref(false),error=ref('');let editing=false;
onLoad(async q=>{editing=q.edit==='1';if(editing)try{const s=await api('bootstrap');daily.value=String(s.user.preferences.daily/100);habit.value=s.user.preferences.habit;}catch(e){error.value=e.message;}});
async function start(){if(busy.value)return;busy.value=true;error.value='';try{await api('settings',{daily:parseMoney(daily.value),habit:habit.value});if(!editing)await api('create',{kind:'self'});home();}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
